fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    // Precondition: 2 ≤ k ≤ s.len()
    // Reverse elements [0..k) in place
    let mut left = 0;
    let mut right = k - 1;
    while left < right {
        s.swap(left, right);
        left += 1;
        right = right.saturating_sub(1);
    }
}